import numpy as np, json
X=np.load('X0.npy').copy()
t=json.load(open('topo.json')); sy=t['sy']; bonds=[tuple(b) for b in t['bonds']]
n=len(sy)
bset=set()
for i,j in bonds: bset.add((min(i,j),max(i,j)))
# angle pairs (1-3)
adj={i:[] for i in range(n)}
for i,j in bonds: adj[i].append(j); adj[j].append(i)
pairs13=set()
for i in range(n):
    for a in adj[i]:
        for b in adj[i]:
            if a<b: pairs13.add((a,b))
b0={}
for i,j in bset: b0[(i,j)]=np.linalg.norm(X[i]-X[j])
a0={}
for i,j in pairs13: a0[(i,j)]=np.linalg.norm(X[i]-X[j])
rad={'H':1.1,'C':1.6,'N':1.5,'P':1.8,'Co':1.6}
# only move atoms that are not core (keep core: Co, Nap, N2, amide N, P, aryl rings) -> move all except first 5
fixed=set([0,1,2,3,4])
for it in range(3000):
    F=np.zeros_like(X)
    for (i,j),r in b0.items():
        d=X[j]-X[i]; L=np.linalg.norm(d); f=10*(L-r)*d/L
        F[i]+=f; F[j]-=f
    for (i,j),r in a0.items():
        d=X[j]-X[i]; L=np.linalg.norm(d); f=5*(L-r)*d/L
        F[i]+=f; F[j]-=f
    D=np.linalg.norm(X[:,None]-X[None],axis=-1)
    for i in range(n):
        for j in range(i+1,n):
            if (i,j) in bset or (i,j) in pairs13: continue
            rmin=rad[sy[i]]+rad[sy[j]]
            if D[i,j]<rmin:
                d=X[j]-X[i]; L=D[i,j]
                f=3*(L-rmin)*d/L
                F[i]+=f; F[j]-=f
    for i in fixed: F[i]=0
    X+=0.02*F
    if it%500==0:
        print(it, np.abs(F).max())
# report
D=np.linalg.norm(X[:,None]-X[None],axis=-1); np.fill_diagonal(D,99)
mins=[]
for i in range(n):
    for j in range(i+1,n):
        if (i,j) in bset or (i,j) in pairs13: continue
        mins.append((round(D[i,j],2),sy[i],i,sy[j],j))
mins.sort()
print(mins[:10])
err=[(round(abs(np.linalg.norm(X[i]-X[j])-r),3),sy[i],sy[j]) for (i,j),r in b0.items()]
print('max bond err',max(err))
with open('init.xyz','w') as f:
    f.write(f"{n}\nrelaxed guess\n")
    for s,p in zip(sy,X): f.write(f"{s} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
